"""Autogenerated private Kaggle entrypoint. Placeholders replaced offline."""
from __future__ import annotations
import base64
import io
import json
import os
import subprocess
import sys
import traceback
import zipfile
from pathlib import Path

CONFIG_B64 = "__TW_SHORTS_JOB_B64__"
SOURCE_B64 = "__TW_SHORTS_SOURCE_B64__"
BASE = Path('/kaggle/working/tw_short_modules')
OUT = Path('/kaggle/working')


def main():
    conf = json.loads(base64.b64decode(CONFIG_B64))
    package = base64.b64decode(SOURCE_B64)
    BASE.mkdir(parents=True, exist_ok=True)
    with zipfile.ZipFile(io.BytesIO(package)) as z:
        for member in z.infolist():
            rel = Path(member.filename)
            if rel.is_absolute() or '..' in rel.parts or not str(rel).startswith('studio/'):
                raise RuntimeError('Unsafe source module archive')
        z.extractall(BASE)
    sys.path.insert(0, str(BASE))
    phase = conf['phase']
    gpu_id = conf['gpu_id']
    if phase in {'image', 'voice'}:
        os.environ['CUDA_VISIBLE_DEVICES'] = str(gpu_id)
    if conf.get('install_deps') and phase in {'image', 'voice'}:
        packages = (['qwen-tts', 'soundfile'] if phase == 'voice' else
                    ['diffusers', 'transformers', 'accelerate', 'safetensors'])
        subprocess.run([sys.executable, '-m', 'pip', 'install', '-q', *packages],
                       check=True, timeout=1200)
    # Optional explicit cache bootstrap. Defaults off: model weights should be
    # preattached via a private Kaggle model dataset to conserve GPU quota.
    model_root = Path(conf['model_path'])
    if conf.get('bootstrap') and phase in {'image', 'voice'}:
        from huggingface_hub import snapshot_download
        mapping = {'image': 'black-forest-labs/FLUX.2-klein-4B',
                   'voice': 'Qwen/Qwen3-TTS-12Hz-0.6B-CustomVoice'}
        dst = model_root / phase
        dst.mkdir(parents=True, exist_ok=True)
        snapshot_download(repo_id=mapping[phase], local_dir=str(dst))
    from studio.kaggle_shorts_worker import main as worker
    args = ['--source', conf['source_path'], '--story', conf['story'],
            '--phase', phase, '--models', str(model_root),
            '--work', '/kaggle/working/tw_private_project',
            '--out', '/kaggle/working', '--start', str(conf['first_scene']),
            '--count', str(conf['max_scenes']), '--time-budget', str(conf['budget_s']),
            '--gpu-id', str(gpu_id), '--speaker', conf['speaker']]
    if conf.get('recovery_path'):
        args += ['--recovery', conf['recovery_path']]
    code = worker(args)
    if code != 0:
        raise SystemExit(code)


if __name__ == '__main__':
    main()